import { line } from 'axylo';

/**
 * Line chart options for the daily visits rows (`{ day, visits }`).
 *
 * - `day` arrives as a UTC-midnight instant ('2026-03-01T00:00:00Z'). `type: 'date'` reads each one
 *   as its calendar day in UTC, so every viewer sees the same date (no off-by-one-day west of UTC).
 * - Rows may come in any order: Axylo sorts dated rows by x and keeps each value with its row.
 * - Days with no row inside the range are drawn as gaps (Axylo infers them on a regular daily axis),
 *   never as zeros and never bridged by a straight line.
 *
 * @param {readonly { day: string, visits: number | null }[]} data
 */
export function visitsOptions(data) {
  return {
    title: 'Daily visits',
    data,
    x: { field: 'day', type: 'date' },
    y: { field: 'visits', label: 'Visits' },
  };
}

/**
 * Draws the daily visits line chart into `element`.
 *
 * @param {HTMLElement} element The chart container.
 * @param {readonly { day: string, visits: number | null }[]} data The rows from data.json.
 * @returns The Axylo chart handle.
 */
export default function render(element, data) {
  return line(element, visitsOptions(data));
}

