input.command:
node --input-type=module -e "
import { readFileSync } from 'node:fs';
import { validate } from 'axylo';
import render, { visitsOptions } from './chart.js';
const rows = JSON.parse(readFileSync('data.json', 'utf8'));
console.log('render is', typeof render, '/ arity', render.length);
const problems = validate('line', visitsOptions(rows));
for (const d of problems) console.log(d.code, d.level, d.field ?? '-', '|', d.message);
const blocking = problems.filter(d => d.level !== 'hint');
console.log('total', problems.length, 'blocking', blocking.length);
// Compare: without type 'date' (expect AX111)
for (const d of validate('line', { ...visitsOptions(rows), x: 'day' })) console.log('[no type:date]', d.code, d.level);
"

